def push_bounded(stack, item, capacity):
    if len(stack) >= capacity:
        return False
    stack.append(item)
    return True

pairs = {')': '(', ']': '[', '}': '{'}
stack = []
for index, char in enumerate(text):
    if char in pairs.values():
        stack.append((char, index))
    elif char in pairs:
        if not stack or stack[-1][0] != pairs[char]:
            return False, index
        stack.pop()
return (not stack), None

